head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil05504";
scwin.upd_attachMovie = null;
scwin.upd_attachFile0 = null;
scwin.upd_attachFile1 = null;
scwin.upd_attachFile2 = null;
scwin.upd_attachFile3 = null;
scwin.upd_attachFile4 = null;
scwin.chkFile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_pageBody
 * @description TODO Stage2: 컨텍스트 키 출처 미확인(as-is EL · 회신 A-3) — loadTp, uploadCodeFile, uploadCodeMovie
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        const loadTp = (String(((dma_pageContext.get("loadTp") ?? "")) == null ? '' : ((dma_pageContext.get("loadTp") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("loadTp") ?? "")) == null ? '' : ((dma_pageContext.get("loadTp") ?? ""))));
        if (loadTp === '2') {
            await scwin.checkSave();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil05504.onpageload' }); }
};

// 세션 사용자 결선 (어휘 session_attribute 1건 — gcc $c.session.getUserInfo)

/**
 * @method
 * @name init_sessionFill
 * @description 초기화 — session Fill
 * @returns {void}
 * @hidden N
 */
scwin.init_sessionFill = function () {
    const names = ["usrId"];
    function fill() {
        for (let i = 0; i < names.length; i++) {
            let v; try { v = $c.session.getUserInfo(names[i]); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldfil05504' }); v = undefined; }
            if (v === undefined || v === null || v === '') { continue; }
            const token = '${session.user.' + names[i] + '}';
            let r0 = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document); r0 = r0.body || r0; const doc = r0.ownerDocument || r0; const w = doc.createTreeWalker(r0, NodeFilter.SHOW_TEXT);
            let n; while ((n = w.nextNode())) { if (n.nodeValue.indexOf(token) >= 0) { n.nodeValue = n.nodeValue.split(token).join(v); } }
            const ins = ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelectorAll('input, textarea');
            for (let j = 0; j < ins.length; j++) { if (ins[j].value && ins[j].value.indexOf(token) >= 0) { ins[j].value = ins[j].value.split(token).join(v); } }
        }
    }
    fill();
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.upd_attachMovie = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachMovie') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachMovie"]');
        scwin.upd_attachFile0 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile0') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile0"]');
        scwin.upd_attachFile1 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile1') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile1"]');
        scwin.upd_attachFile2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile2"]');
        scwin.upd_attachFile3 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile3') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile3"]');
        scwin.upd_attachFile4 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachFile4') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachFile4"]');
        scwin.chkFile = chkFile;
        scwin.init_sessionFill();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldfil05504.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
