///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Search
 * @description Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Search = async function () {
    const sbmOptions = {
        id: "tx_fn_Search",
        method: "post",
        action: "/list/irData.do",
        ref: "dma_SearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_Register
 * @description Register 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Register = async function () {
    const sbmOptions = {
        id: "tx_fn_Register",
        method: "post",
        action: "/list/irData.do",
        ref: "dma_RegisterReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkSave
 * @description check Save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkSave = async function () {
    const uploadCodeFile = (String(((dma_pageContext.get("uploadCodeFile") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCodeFile") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCodeFile") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCodeFile") ?? ""))));
    const uploadCodeMovie = (String(((dma_pageContext.get("uploadCodeMovie") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCodeMovie") ?? ""))).indexOf('$' + '{') >= 0 ? '' : String(((dma_pageContext.get("uploadCodeMovie") ?? "")) == null ? '' : ((dma_pageContext.get("uploadCodeMovie") ?? ""))));
    if (uploadCodeFile === '0') {
        if (uploadCodeMovie === '0') {
            await $c.win.alert('저장되었습니다.');
        } else {
            if (uploadCodeMovie === '1') {
                await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
            } else {
                if (uploadCodeMovie === '2') {
                    await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
                } else {
                    await $c.win.alert('저장시 오류가 발생하였습니다.');
                }
            }
        }
    } else {
        if (uploadCodeFile === '1') {
            await $c.win.alert('해당유형의 파일은 업로드할 수 없습니다.');
        } else {
            if (uploadCodeFile === '2') {
                await $c.win.alert('업로드 하려는 파일의 크기가 허용한도를 초과 하였습니다.');
            } else {
                await $c.win.alert('저장시 오류가 발생하였습니다.');
            }
        }
    }
};

/**
 * @method
 * @name validate
 * @description validate 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.validate = async function (obj) {
    const arrVar = ['title', 'resoroomContn'];
    const fileVar = ['attachMovieSize', 'attachFile0Size', 'attachFile1Size', 'attachFile2Size', 'attachFile3Size', 'attachFile4Size'];
    if (!await scwin.isValid(obj, arrVar) || !await scwin.chkFileTotalSize(fileVar)) {
        return false;
    } else {
        return true;
    }
};

/**
 * @method
 * @name isValid
 * @description is Valid 처리
 * @param {Object} obj 컴포넌트
 * @param {*} arrVar arrVar
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.isValid = async function (obj, arrVar) {
    for (i = 0; i < arrVar.length; i++) {
        const arrObj = (obj + '.' + arrVar[i]);
        if (arrObj.value === '') {
            await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))(arrObj) + '(은)는 반드시 입력하셔야 합니다.');
            arrObj.focus();
            return false;
        }
    }
    return true;
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    (document.irDataListForm || { elements: [] }).action = '/list/irData.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'searchIRData');
    const nr = await scwin.tx_fn_Search();
    if (nr && nr.responseJSON && nr.responseJSON.success === true) {
        $c.win.moveUrl("/jldfil21210/jldfil21210.xml", { "method": 'searchIRData' });
    }
};

/**
 * @method
 * @name register
 * @description register 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function () {
    (document.irDataForm || { elements: [] }).action = '/list/irData.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'registerIRData');
    if (await scwin.validate('document.irDataForm')) {
        if (await $c.win.confirm("등록하시겠습니까?")) {
            await scwin.tx_fn_Register();
        }
    } else {
        return;
    }
};

async function chkFile(obj) {
    if (obj.value === '') {
        return false;
    }
    const notFileType = ["js", "css", "html", "htm", "xml", "jsp", "asp", "php"];
    const fileFullNm = obj.value;
    const fileNm = fileFullNm.substring(fileFullNm.lastIndexOf("\\") + 1);
    const fileType = fileFullNm.substring(fileFullNm.lastIndexOf(".") + 1).toLowerCase();
    for (i = 0; i < notFileType.length; i++) {
        if (notFileType[i] === fileType) {
            await $c.win.alert("선택하신 파일(" + fileNm + ")에서 " + notFileType[i] + " 파일 확장자는 사용하실 수 없습니다.");
            ($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setValue) ? $c.util.getComponent(obj.parentNode.id).setValue("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setText) ? $c.util.getComponent(obj.parentNode.id).setText("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + obj.parentNode.id), void ("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />")));
            return false;
        }
    }
    const fileSize = 1024;
    if (fileSize / 1024 > 30720) {
        await $c.win.alert("선택하신 " + fileNm + " 파일의 최대 크기는 30M를 넘을 수 없습니다.");
        ($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setValue) ? $c.util.getComponent(obj.parentNode.id).setValue("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setText) ? $c.util.getComponent(obj.parentNode.id).setText("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + obj.parentNode.id), void ("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />")));
        return false;
    }
    $c.util.getComponent(obj.id + "Size").setValue(fileSize);
}

/**
 * @method
 * @name chkFileTotalSize
 * @description chk File Total Size 처리
 * @param {*} fileVar fileVar
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.chkFileTotalSize = async function (fileVar) {
    let totalSum = 0;
    for (let i = 0; i < fileVar.length; i++) {
        const attachFileSize = $c.util.getComponent(fileVar[i]).getValue();
        if (attachFileSize !== '') {
            totalSum = totalSum + (attachFileSize);
        }
    }
    if (totalSum / 1024 > 102400) {
        await $c.win.alert("첨부파일 및 동영상의 총 파일 크기는 100M를 넘을 수 없습니다. ");
        return false;
    }
    return true;
};

/**
 * @method
 * @name getByteLength2
 * @description 바이트 수(as-is 공통 fn_GetByte 계산 — 한글 2byte · 줄바꿈 2byte · 그 밖 1byte)
 * @param {*} value 문자열
 * @returns {Number} 바이트 수
 * @hidden N
 */
scwin.getByteLength2 = function (value) {
    const s = String(value ?? "");
    let n = 0;
    for (let i = 0; i < s.length; i++) {
        const ch = s.charAt(i);
        n += (ch === "\n" || ch.charCodeAt(0) > 127) ? 2 : 1;
    }
    return n;
};

/**
 * @method
 * @name truncateByBytes
 * @description 바이트 상한을 넘는 뒷부분을 잘라낸다(as-is 공통 fn_CalcContn 계산 — 한글 2 · '<' '>' 4 · 줄바꿈 1)
 * @param {*} value 문자열
 * @param {*} maximum 바이트 상한
 * @returns {String} 잘린 문자열
 * @hidden N
 */
scwin.truncateByBytes = function (value, maximum) {
    const s = String(value ?? "");
    let out = "", bytes = 0;
    for (let i = 0; i < s.length; i++) {
        const ch = s.charAt(i);
        let inc = 1;
        if (ch === "\n") { inc = (s.charAt(i - 1) !== "\r") ? 1 : 0; }
        else if (ch.charCodeAt(0) > 127) { inc = 2; }
        else if (ch === "<" || ch === ">") { inc = 4; }
        bytes += inc;
        if (bytes > Number(maximum)) { break; }
        out += ch;
    }
    return out;
};

/**
 * @method
 * @name checkByteLimit
 * @description 입력 바이트 상한 검사 — 카운터 표시, 초과분은 알린 뒤 자동 삭제(as-is 공통 fn_CheckByte)
 * @param {Object} comp 입력 컴포넌트
 * @param {*} standardByte 바이트 상한
 * @param {String} counterId 카운터 표시 컴포넌트 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkByteLimit = async function (comp, standardByte, counterId) {
    const limit = Number(standardByte);
    let bytes = scwin.getByteLength2(comp.getValue());
    if (bytes > limit) {
        await $c.win.alert((bytes - limit) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.");
        comp.setValue(scwin.truncateByBytes(comp.getValue(), limit));
        bytes = scwin.getByteLength2(comp.getValue());
    }
    const counter = $c.util.getComponent(counterId);
    if (counter) { counter.setValue("(" + bytes + "/" + limit + " byte)"); }
};
